use vstd::prelude::*;

verus! {

/// Extract the decimal digits of a 4-digit number n:
/// thousands t, hundreds h, tens te, ones o.
spec fn thou(n: int) -> int { n / 1000 }
spec fn hund(n: int) -> int { (n / 100) % 10 }
spec fn tens(n: int) -> int { (n / 10) % 10 }
spec fn ones(n: int) -> int { n % 10 }

/// The desired property:
/// - first three digits equal: t == h == te
/// - last three digits equal:  h == te == o
spec fn has_three_equal_adjacent(n: int) -> bool {
    (thou(n) == hund(n) && hund(n) == tens(n))
    || (hund(n) == tens(n) && tens(n) == ones(n))
}

fn solve(n: i8) -> (res: bool)
    requires
        1000 <= n as int <= 9999,
    ensures
        res <==> has_three_equal_adjacent(n as int),
{
    // Compute digits using integer arithmetic.
    let ni: int = n as int;

    let t: int = ni / 1000;
    let h: int = (ni / 100) % 10;
    let te: int = (ni / 10) % 10;
    let o: int = ni % 10;

    // (Optional) sanity facts from the range; useful for the verifier in some settings.
    assert(0 <= t && t <= 9);
    assert(0 <= h && h <= 9);
    assert(0 <= te && te <= 9);
    assert(0 <= o && o <= 9);

    let first3: bool = (t == h) && (h == te);
    let last3: bool = (h == te) && (te == o);
    let out: bool = first3 || last3;

    // Connect implementation booleans to the spec.
    assert(first3 <==> (thou(ni) == hund(ni) && hund(ni) == tens(ni)));
    assert(last3  <==> (hund(ni) == tens(ni) && tens(ni) == ones(ni)));
    assert(out <==> has_three_equal_adjacent(ni));

    out
}

} // verus!

